// Route 280 data model. The JSON is generated by tools/build_route.py from
// OpenStreetMap data (stop poles matched by official stop codes) and can be
// edited independently of the world geometry.
import { PathSampler } from '../core/path.js';

/** Distance (m) the bus front stops beyond the stop pole projection, so the front door is level with the pole. */
export const FRONT_STOP_OFFSET = 1.6;

export class Route280 {
  constructor(json) {
    this.json = json;
    this.line = json.line;
    this.dirs = {};
    for (const id of Object.keys(json.directions)) {
      const d = json.directions[id];
      const path = new PathSampler(d.path);
      const stops = d.stops.map((s, i) => ({
        ...s,
        index: i,
        dir: id,
        frontS: Math.min(s.s + FRONT_STOP_OFFSET, path.length - 0.5),
        isFirst: i === 0,
        isLast: i === d.stops.length - 1,
      }));
      this.dirs[id] = {
        id,
        headsign: d.headsign,
        from: d.from_,
        stops,
        path,
        lane: d.lane,
        length: path.length,
        streets: d.streets,
      };
    }
    this.terminalLinks = json.terminalLinks || {};
  }

  direction(id) {
    const d = this.dirs[id];
    if (!d) throw new Error(`unknown direction ${id}`);
    return d;
  }

  other(id) {
    return id === 'A' ? 'B' : 'A';
  }

  /** Half width of the carriageway (m) and oneway flag at arc length s. */
  laneInfo(id, s) {
    const d = this.direction(id);
    const i = d.path.index(s);
    const [hw, ow] = d.lane[Math.min(i, d.lane.length - 1)];
    return { halfWidth: hw / 10, oneway: !!ow };
  }

  /** Lateral offset (m, to the right of the path centre line) of the kerb-side lane centre. */
  laneOffset(id, s, atStop = false) {
    const { halfWidth } = this.laneInfo(id, s);
    const busHalf = 1.28;
    const gap = atStop ? 0.25 : 0.55;
    return Math.max(0, halfWidth - busHalf - gap);
  }

  /** Scheduled running time (s) from the trip start to each stop: cruise ~ 6.3 m/s incl. junction delays + 22 s dwell. */
  schedule(id) {
    const d = this.direction(id);
    return d.stops.map((st, i) => Math.round(st.s / 6.3 + i * 22));
  }

  allStopNames() {
    const out = new Set();
    for (const d of Object.values(this.dirs)) for (const s of d.stops) out.add(s.name);
    return [...out];
  }
}
